CREATE OR ALTER PROCEDURE [dbo].[uspApprovalItem_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @ApprovalRequestId UNIQUEIDENTIFIER = NULL
	, @ItemType NVARCHAR(MAX) = NULL
	, @ItemId UNIQUEIDENTIFIER = NULL
	, @ItemStatus NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[ApprovalRequestId]
			, t.[ItemType]
			, t.[ItemId]
			, t.[ActionCode]
			, t.[PayloadJson]
			, t.[ItemStatus]
			, t.[CreatedDate]
		FROM [dbo].[ApprovalItem] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[ActionCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (@ApprovalRequestId IS NULL OR t.[ApprovalRequestId] = @ApprovalRequestId)
			AND (ISNULL(@ItemType, '') = '' OR t.[ItemType] = @ItemType)
			AND (@ItemId IS NULL OR t.[ItemId] = @ItemId)
			AND (ISNULL(@ItemStatus, '') = '' OR t.[ItemStatus] = @ItemStatus)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'approvalRequestId' THEN r.[ApprovalRequestId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'approvalRequestId' THEN r.[ApprovalRequestId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'itemType' THEN r.[ItemType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'itemType' THEN r.[ItemType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'itemId' THEN r.[ItemId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'itemId' THEN r.[ItemId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'actionCode' THEN r.[ActionCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'actionCode' THEN r.[ActionCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'payloadJson' THEN r.[PayloadJson] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'payloadJson' THEN r.[PayloadJson] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'itemStatus' THEN r.[ItemStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'itemStatus' THEN r.[ItemStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
